use crate::model::{Event,Summary};
pub fn valid_amount(value:i64)->bool {value>=0 && value<=1000000}
struct State {balance:i64,rejected:i64,peak:i64,locked:bool,audit:Vec<i64> ,history:Vec<i64>}
fn step(mut state:State,event:&Event)->State {
 match *event {
  Event::Credit(amount)=> {if valid_amount(amount) {state.history.push(state.balance); state.balance+=amount;} else {state.rejected+=1;}},
  Event::Debit(amount)=> {if !valid_amount(amount) || state.locked || amount>state.balance {state.rejected+=1;} else {state.history.push(state.balance); state.balance-=amount;}},
  Event::Lock=>state.locked=true,Event::Unlock=>state.locked=false ,Event::Undo=> {if state.locked || state.history.is_empty() {state.rejected+=1;} else {state.balance=state.history.pop().unwrap();}}
 }
 state.peak=state.peak.max(state.balance);state.audit.push(state.balance);state
}
pub fn run(events:&[Event],initial:i64)->Summary {
 let mut state=State {balance:initial,rejected:0,peak:initial,locked:false,audit:Vec::new() ,history:Vec::new()};
 for event in events {state=step(state,event);}
 Summary {balance:state.balance,rejected:state.rejected,peak:state.peak,audit:state.audit}
}

